// Package eject renders a generated file map into a complete, buildable Expo
// project (for eas build), distinct from the live on-device path.
package eject

import (
	"archive/zip"
	"bytes"
	_ "embed"
	"fmt"
	"sort"

	"github.com/joakimcarlsson/vibe/internal/generator"
)

//go:embed assets/vibe-router.tsx
var vibeRouterSrc string

//go:embed assets/Root.tsx
var rootSrc string

// Zip renders the project and returns it as an in-memory zip archive.
func Zip(files []generator.File) ([]byte, error) {
	project := scaffold(files)

	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)

	paths := make([]string, 0, len(project))
	for p := range project {
		paths = append(paths, p)
	}
	sort.Strings(paths)

	for _, p := range paths {
		w, err := zw.Create(p)
		if err != nil {
			return nil, fmt.Errorf("eject: %w", err)
		}
		if _, err := w.Write([]byte(project[p])); err != nil {
			return nil, fmt.Errorf("eject: %w", err)
		}
	}
	if err := zw.Close(); err != nil {
		return nil, fmt.Errorf("eject: %w", err)
	}
	return buf.Bytes(), nil
}

// scaffold merges the generated files with the project template. The generated
// entry App.tsx is wrapped by Root.tsx (which loads fonts) and registered via
// index.js; the @vibe/router import is aliased to the bundled router source.
func scaffold(files []generator.File) map[string]string {
	out := make(map[string]string, len(files)+8)
	for _, f := range files {
		out[f.Path] = f.Content
	}
	out["vibe-router.tsx"] = vibeRouterSrc
	out["Root.tsx"] = rootSrc
	out["index.js"] = indexJS
	out["package.json"] = packageJSON
	out["app.json"] = appJSON
	out["babel.config.js"] = babelConfig
	out["tsconfig.json"] = tsconfigJSON
	out["README.md"] = readme
	return out
}

const indexJS = `import { registerRootComponent } from 'expo';

import Root from './Root';

registerRootComponent(Root);
`

