const babelConfig = `module.exports = function (api) {
  api.cache(true);
  return {
    presets: ['babel-preset-expo'],
    plugins: [['module-resolver', { alias: { '@vibe/router': './vibe-router' } }]],
  };
};
`

const tsconfigJSON = `{
  "extends": "expo/tsconfig.base",
  "compilerOptions": {
    "strict": true
  }
}
`

const readme = `# VIBE app (ejected)

This is a complete Expo project generated by VIBE. Unlike the live VIBE preview,
this runs as a normal React Native app you own and can ship.

## Run locally

` + "```" + `bash
npm install
npx expo install --fix   # align native deps to the installed Expo SDK
npx expo run:android     # or: npx expo run:ios
` + "```" + `

## Build for the stores (EAS)

` + "```" + `bash
npm install -g eas-cli
eas login
eas build:configure
eas build --platform android   # or: --platform ios
` + "```" + `

## Notes

- ` + "`@vibe/router`" + ` is a small bundled navigator (see ` + "`vibe-router.tsx`" + `),
  aliased in ` + "`babel.config.js`" + `.
- ` + "`Root.tsx`" + ` loads the fonts VIBE apps expect, then renders ` + "`App.tsx`" + `.
`
